Recommendation is a single-pod service that disappears entirely in the incident window, and the frontend's `/recommendations` path is the only user-facing effect. Ready to write up.

```json
{
  "root_causes": [
    {
      "service": "recommendation",
      "fault_kind": "pod_unavailable",
      "evidence": [
        {"kind": "metric", "sql": "SELECT metric, service_name, round(avg(value),2) AS avgv, min(time) AS t0, max(time) AS t1 FROM abnormal_metrics WHERE metric='k8s.deployment.available' AND service_name IN ('recommendation','frontend') GROUP BY 1,2", "claim": "recommendation deployment availability is 0 from 23:06:35 through the end of the window, while frontend stays at 1"},
        {"kind": "trace", "sql": "SELECT 'normal' AS p, count(*) AS spans FROM normal_traces WHERE service_name='recommendation' UNION ALL SELECT 'abnormal', count(*) FROM abnormal_traces WHERE service_name='recommendation'", "claim": "recommendation emits 735 spans in the normal window and none in the abnormal window"},
        {"kind": "trace", "sql": "SELECT span_name, attr_span_kind, count(*) AS n, round(avg(duration)/1e6,3) AS avg_ms FROM abnormal_traces WHERE service_name='frontend' AND span_name LIKE '%ecommend%' GROUP BY 1,2", "claim": "frontend's GetRecommendations client calls all fail: 246 calls, avg 0.02 ms, with the matching HTTP /recommendations spans returning 500"}
      ]
    }
  ],
  "propagation": [
    {"from": "recommendation", "to": "frontend", "evidence": [{"kind": "trace", "sql": "SELECT service_name, span_name, attr_http_response_status_code AS status, attr_status_code, count(*) AS n FROM abnormal_traces WHERE service_name='frontend' AND (span_name LIKE 'HTTP /recommendations%' OR span_name LIKE 'recommendation.%') GROUP BY 1,2,3,4", "claim": "Frontend /recommendations server spans return HTTP 500 with Error status; the recommendation client calls fail with it"}]}
  ]
}
```

